// ── Resource coverage ──────────────────────────────────────────────
// Unavailable: carrier   — Omniva is a single-carrier postal operator; no carrier listing endpoint exists in the OMX API
// Unavailable: manifest  — official docs state manifests must be generated by the customer's own system; no API endpoint provided
// Unavailable: order     — Omniva OMX API has no order-management concept; it is a carrier/postal API, not an OMS
// Unavailable: rate      — no rate-calculation endpoint documented in the OMX API
// Unavailable: warehouse — no warehouse management endpoint documented in the OMX API

import type { LogisticsAdapter, Credentials, QueryParams } from '../../adapter/interface'
import type { Shipment } from '../../schema/shipment'
import type { TrackingEvent } from '../../schema/trackingevent'
import type { Label } from '../../schema/label'

import { buildAuthUrl, exchangeApiKey, refreshCredentials as doRefresh } from './auth'
import { OmnivaClient } from './client'

import { transformTracking, type OmnivaTrackingResponse } from './transform/tracking'
import { transformShipment, type OmnivaParcel } from './transform/shipment'
import { transformLabels, type OmnivaPackageLabelsResponse } from './transform/label'

interface OmnivaAdapterConfig {
  sandbox?: boolean
}

export class OmnivaAdapter implements LogisticsAdapter {
  readonly platform = 'omniva'
  readonly version = '1'

  constructor(_config: OmnivaAdapterConfig = {}) {}

  // ── Auth ───────────────────────────────────────────────────────────────────

  getAuthUrl(state: string): string {
    return buildAuthUrl(state)
  }

  async exchangeCode(code: string, _redirectUri: string): Promise<Credentials> {
    // For Omniva the "code" is the "username:password" pair.
    return exchangeApiKey(code)
  }

  async refreshCredentials(credentials: Credentials): Promise<Credentials> {
    return doRefresh(credentials)
  }

  // ── Tracking Events ────────────────────────────────────────────────────────

  async getTrackingEvents(
    credentials: Credentials,
    trackingNumber: string,
  ): Promise<TrackingEvent[]> {
    const client = new OmnivaClient(credentials)
    const raw = await client.get<OmnivaTrackingResponse>(`parcels/${trackingNumber}/tracking`)
    return transformTracking(raw)
  }

  // ── Labels ─────────────────────────────────────────────────────────────────

  /**
   * Refused. The OMX API Manual, section 1.7 "Request label", documents
   * package-labels only as a request for the labels of named barcodes
   * ("barcodes [] yes array, string(5-30) Shipment barcodes that labels are
   * requested for."). There is no label collection to list or page.
   */
  async listLabels(_credentials: Credentials, _params: QueryParams): Promise<Label[]> {
    throw Object.assign(
      new Error(
        'Omniva cannot list labels: the OMX package-labels service only returns labels for the mandatory ' +
          '"barcodes []" it is given ("Shipment barcodes that labels are requested for"); there is no label collection',
      ),
      { statusCode: 501, code: 'NOT_SUPPORTED' },
    )
  }

  async createLabel(credentials: Credentials, data: Partial<Label>): Promise<Label> {
    const client = new OmnivaClient(credentials)
    const raw = await client.post<OmnivaPackageLabelsResponse>('shipments/package-labels', {
      barcodes: data.trackingNumber ? [data.trackingNumber] : [],
      sendAddressCardTo: 'RESPONSE',
    })
    const labels = transformLabels(raw)
    return labels[0] ?? { carrierId: 'omniva', status: 'CREATED' }
  }

  // ── Shipments ──────────────────────────────────────────────────────────────

  async createShipment(credentials: Credentials, data: Partial<Shipment>): Promise<Shipment> {
    const client = new OmnivaClient(credentials)
    const raw = await client.post<OmnivaParcel>('parcels', {
      sender: data.originAddress
        ? {
            name: data.originAddress.name,
            company: data.originAddress.company,
            street1: data.originAddress.street1,
            street2: data.originAddress.street2,
            city: data.originAddress.city,
            postal_code: data.originAddress.postalCode,
            country: data.originAddress.country,
            phone: data.originAddress.phone,
            email: data.originAddress.email,
          }
        : undefined,
      recipient: data.destinationAddress
        ? {
            name: data.destinationAddress.name,
            company: data.destinationAddress.company,
            street1: data.destinationAddress.street1,
            street2: data.destinationAddress.street2,
            city: data.destinationAddress.city,
            postal_code: data.destinationAddress.postalCode,
            country: data.destinationAddress.country,
            phone: data.destinationAddress.phone,
            email: data.destinationAddress.email,
          }
        : undefined,
      weight: data.totalWeight
        ? { value: data.totalWeight.value, unit: data.totalWeight.unit }
        : undefined,
      reference: data.reference,
      service_code: data.serviceCode,
    })
    return transformShipment(raw)
  }
}
